import type { FlowStep } from "../shared/schema";
import { findElementByTarget } from "../shared/selector";

export type ReplayStepResult = { ok: true } | { ok: false; error: string };

const delay = (durationMs: number): Promise<void> => new Promise((resolve) => window.setTimeout(resolve, durationMs));

const waitForElement = async (step: FlowStep, timeoutMs = 8000): Promise<Element> => {
  const startedAt = Date.now();

  while (Date.now() - startedAt < timeoutMs) {
    if (step.target) {
      const element = findElementByTarget(step.target);
      if (element) {
        return element;
      }
    }

    await delay(200);
  }

  throw new Error(`找不到元素：${step.target?.selector ?? step.target?.text ?? step.id}`);
};

const dispatchInputEvents = (element: Element): void => {
  try {
    element.dispatchEvent(new InputEvent("beforeinput", { bubbles: true, cancelable: true, inputType: "insertText" }));
  } catch {
    element.dispatchEvent(new Event("beforeinput", { bubbles: true, cancelable: true }));
  }

  try {
    element.dispatchEvent(new InputEvent("input", { bubbles: true, inputType: "insertText" }));
  } catch {
    element.dispatchEvent(new Event("input", { bubbles: true }));
  }

  element.dispatchEvent(new Event("change", { bubbles: true }));
};

const setNativeInputValue = (element: HTMLInputElement | HTMLTextAreaElement, value: string): void => {
  const prototype = Object.getPrototypeOf(element);
  const descriptor = Object.getOwnPropertyDescriptor(prototype, "value");
  const setter = descriptor?.set;

  if (setter) {
    setter.call(element, value);
  } else {
    element.value = value;
  }
};

const setElementValue = (element: Element, value: FlowStep["value"]): void => {
  if (value === undefined) {
    return;
  }

  if (element instanceof HTMLInputElement) {
    if (element.type === "password" && value === "[password]") {
      throw new Error("密码字段没有记录真实值。请录制前勾选“记录真实密码用于回放”，然后重新录制。");
    }

    element.focus();
    element.dispatchEvent(new FocusEvent("focus", { bubbles: true }));

    if (element.type === "checkbox" || element.type === "radio") {
      element.checked = Boolean(value);
    } else {
      setNativeInputValue(element, String(value));
    }
    dispatchInputEvents(element);
    return;
  }

  if (element instanceof HTMLTextAreaElement) {
    element.focus();
    element.dispatchEvent(new FocusEvent("focus", { bubbles: true }));
    setNativeInputValue(element, String(value));
    dispatchInputEvents(element);
    return;
  }

  if (element instanceof HTMLSelectElement) {
    element.value = String(value);
    dispatchInputEvents(element);
  }
};

const clickElement = (element: Element): void => {
  const clickTarget = element.closest("a, button, [role='button'], input[type='button'], input[type='submit']") ?? element;
  const clickable = clickTarget as HTMLElement;
  clickable.focus();
  clickable.dispatchEvent(new PointerEvent("pointerdown", { bubbles: true, cancelable: true, pointerType: "mouse" }));
  clickable.dispatchEvent(new MouseEvent("mousedown", { bubbles: true, cancelable: true }));
  clickable.dispatchEvent(new PointerEvent("pointerup", { bubbles: true, cancelable: true, pointerType: "mouse" }));
  clickable.dispatchEvent(new MouseEvent("mouseup", { bubbles: true, cancelable: true }));
  clickable.click();
};

export const runReplayStep = async (step: FlowStep): Promise<void> => {
  if (step.type === "wait") {
    await delay(step.waitMs ?? 500);
    return;
  }

  if (step.type === "navigate" || step.type === "postmessage") {
    return;
  }

  if (step.type === "scroll" && step.scroll) {
    window.scrollTo({ left: step.scroll.x, top: step.scroll.y, behavior: "smooth" });
    await delay(400);
    return;
  }

  if (!step.target) {
    return;
  }

  const element = await waitForElement(step);
  element.scrollIntoView({ block: "center", inline: "center", behavior: "smooth" });
  await delay(300);

  if (step.type === "click" || step.type === "submit") {
    clickElement(element);
    return;
  }

  if (step.type === "input" || step.type === "change") {
    setElementValue(element, step.value);
    return;
  }

  if (step.type === "keydown" && step.key) {
    element.dispatchEvent(new KeyboardEvent("keydown", { key: step.key, bubbles: true }));
    if (step.key === "Enter") {
      element.dispatchEvent(new KeyboardEvent("keyup", { key: step.key, bubbles: true }));
    }
  }
};

export const executeReplayStep = async (step: FlowStep): Promise<ReplayStepResult> => {
  try {
    await runReplayStep(step);
    return { ok: true };
  } catch (error: unknown) {
    return { ok: false, error: error instanceof Error ? error.message : String(error) };
  }
};
