import type { FlowStep, ReplayRequest, RuntimeMessage } from "../shared/schema";
import { executeReplayStep, runReplayStep } from "./replay-step";

declare global {
  interface Window {
    __MV3_RECORDER_REPLAY_READY__?: boolean;
    __mv3ExecuteReplayStep?: (step: FlowStep) => ReturnType<typeof executeReplayStep>;
  }
}

window.__mv3ExecuteReplayStep = executeReplayStep;

const replayFlow = async (steps: FlowStep[]): Promise<void> => {
  for (const step of steps) {
    await runReplayStep(step);
    await new Promise((resolve) => window.setTimeout(resolve, 400));
  }
};

if (!window.__MV3_RECORDER_REPLAY_READY__) {
  window.__MV3_RECORDER_REPLAY_READY__ = true;

  chrome.runtime.onMessage.addListener((message: RuntimeMessage, _sender, sendResponse) => {
    if (message.type === "REPLAY_STEP") {
      executeReplayStep(message.step)
        .then((result) => sendResponse(result))
        .catch((error: unknown) =>
          sendResponse({ ok: false, error: error instanceof Error ? error.message : String(error) })
        );

      return true;
    }

    if (message.type !== "REPLAY_FLOW") {
      return false;
    }

    replayFlow((message as ReplayRequest).steps)
      .then(() => sendResponse({ ok: true }))
      .catch((error: unknown) => sendResponse({ ok: false, error: error instanceof Error ? error.message : String(error) }));

    return true;
  });
}
